import sys, re
sys.path.insert(0,'/tmp/probe')
import sep2 as sep, an

def frames(j, keys=(), cols=200, rows=60, args=()):
    o,e,rc = sep.run(args, cols=cols, rows=rows, json_in=j, keys=list(keys)+[b'q'],
                     wait=0.5, key_delay=0.15, final_wait=0.3)
    return an.draws(o), e, rc

def text(j, keys=(), cols=200, rows=60, args=(), frame=-1):
    ds,e,rc = frames(j,keys,cols,rows,args)
    if not ds:
        return None, e, rc
    rr,tl = an.grid(ds[frame])
    return [r.decode('utf-8','replace') for r in rr], e, rc

def p(j, keys=(), cols=200, rows=60, label=None, args=(), frame=-1, raw=False):
    rr,e,rc = text(j,keys,cols,rows,args,frame)
    print('=== %s  rc=%s' % (label or repr(j)[:70], rc))
    if e: print('  STDERR %r' % e)
    if rr is None:
        print('  <no frames>')
    else:
        for r in rr: print('  |'+(repr(r) if raw else r)+'|')
    return rr,e,rc
